const SIX = ['Riceberg Ventures','Siana Capital','247 VC Tech Fund','CedarHill Capital','Rainmatter by Zerodha','Atomic Capital'];
function s(v) { return String(v == null ? '' : v).trim(); }
function norm(x) { return s(x).toLowerCase().replace(/[^a-z0-9]/g, ''); }

const trk = $('Read Deal Tracker').all().map(function (i) { return i.json; });
const inv = $('Read INVESTORS').all().map(function (i) { return i.json; });
const pipe = $input.all().map(function (i) { return i.json; });
if (pipe.length < 500) { throw new Error('ABORT: PIPELINE returned only ' + pipe.length + ' rows'); }
if (trk.length < 200) { throw new Error('ABORT: tracker returned only ' + trk.length + ' rows - looks truncated'); }

const cols = Object.keys(trk[0] || {});
let cInv = null; const cDeals = [];
for (const c of cols) {
  const l = c.toLowerCase();
  if (!cInv && (l.indexOf('investor') >= 0 || l.indexOf('vc name') >= 0)) { cInv = c; }
  if (l.indexOf('deals shared') >= 0 || l.indexOf('latest deal') >= 0 || l.indexOf('picked') >= 0) { cDeals.push(c); }
}

const out = {};
for (const name of SIX) {
  const k = norm(name);
  const rec = inv.filter(function (r) { return norm(r.investor) === k; })[0] || null;
  const tr = [];
  for (const r of trk) {
    if (norm(r[cInv]) !== k) { continue; }
    for (const c of cDeals) {
      for (const d of s(r[c]).split(/[,;\n]/)) { if (s(d).length > 2) { tr.push(s(d)); } }
    }
  }
  const mine = pipe.filter(function (r) { return s(r.investor) === name; });
  out[name] = {
    record: rec ? { sector: s(rec.sector), stage: s(rec.stage), cheque: s(rec.cheque_inr_cr), email: s(rec.email), dnc: s(rec.do_not_contact) } : 'NOT FOUND',
    tracker_already_shared: tr,
    pipeline_total: mine.length,
    pipeline_pending: mine.filter(function (r) { return s(r.deal_shared).toLowerCase() !== 'yes' && s(r.pause) === ''; }).map(function (r) { return s(r.startup); }),
    pipeline_sent: mine.filter(function (r) { return s(r.deal_shared).toLowerCase() === 'yes'; }).map(function (r) { return s(r.startup) + (s(r.investor_response) ? ' [REPLIED]' : ''); })
  };
}
return [{ json: { tracker_rows: trk.length, pipeline_rows: pipe.length, six: out } }];
